// eslint-disable-next-line n/no-extraneous-import
import type { FastifyInstance } from 'fastify';

import { NestFactory } from '@nestjs/core';
import {
  FastifyAdapter,
  type NestFastifyApplication,
} from '@nestjs/platform-fastify';
import { supportedMimeTypes } from 'file-type';
import { once } from 'node:events';
import fs from 'node:fs';
import { createServer, type Server } from 'node:http';
import path from 'node:path';

// eslint-disable-next-line n/no-missing-import -- dist/ is generated by `nest build` before e2e runs
import { AppModule } from '../dist/app.module.js';

/** Fixture directory copied/generated by the global e2e setup. */
export const FIXTURES_DIR = path.join('test', 'results', 'fixtures');

/** MIME type per fixture extension, used by the static fixture server. */
const MIME: Record<string, string> = {
  '.jpg': 'image/jpeg',
  '.mp3': 'audio/mpeg',
  '.mp4': 'video/mp4',
  '.png': 'image/png',
  '.txt': 'text/plain',
};

/**
 * Supertest `.parse` hook that collects the raw body as a Buffer.
 * @param res - HTTP response stream to collect.
 * @param next - Callback receiving the collected body.
 */
export function binaryParser(
  res: NodeJS.ReadableStream,
  next: (error: Error | null, body?: Buffer) => void,
) {
  const chunks: Buffer[] = [];
  res.on('data', (chunk: Buffer) => chunks.push(chunk));
  res.on('end', () => next(null, Buffer.concat(chunks)));
  res.on('error', next);
}

/**
 * Boots the production build of the app without listening on a fixed port;
 * use with `supertest` against `app.getHttpServer()`. Mirrors `main.ts`'s
 * content-type parser setup so raw media uploads work. Caller must close the app.
 * @returns The initialized Nest application.
 */
export async function bootApp(): Promise<NestFastifyApplication> {
  const app = await NestFactory.create<NestFastifyApplication>(
    AppModule,
    new FastifyAdapter(),
  );

  const instance = app.getHttpAdapter().getInstance() as FastifyInstance;
  instance.addContentTypeParser(
    [...supportedMimeTypes, 'application/octet-stream'],
    (request, _, done) => {
      if (request.method.toUpperCase() === 'GET') return done(null, request.raw);
      const contentLength = Number.parseInt(
        request.headers['content-length']?.trim() ?? '0',
      );
      return contentLength > 0
        ? done(null)
        : done(new Error('content-length header must be set and be greater than 0'));
    },
  );

  await app.init();
  await instance.ready();
  return app;
}

/**
 * Extracts the boundary parameter from a multipart content-type header.
 * @param contentType - Header value.
 * @returns Boundary string.
 */
export function multipartBoundary(contentType: string): string {
  const match = /boundary="?([^";]+)"?/.exec(contentType);
  const boundary = match?.[1];
  if (!boundary) throw new Error(`no boundary in content-type: ${contentType}`);
  return boundary;
}

/**
 * Splits a multipart/mixed buffer into its raw parts.
 * @param body - Full multipart body.
 * @param boundary - Boundary from the content-type header.
 * @returns Parts with headers and body.
 */
export function parseMultipart(
  body: Buffer,
  boundary: string,
): Array<{ body: Buffer; headers: Record<string, string>; }> {
  const delimiter = Buffer.from(`--${boundary}`);
  const segments: Buffer[] = [];
  let offset = 0;
  while (true) {
    const start = body.indexOf(delimiter, offset);
    if (start === -1) break;
    const nextStart = body.indexOf(delimiter, start + delimiter.length);
    if (nextStart === -1) break;
    segments.push(body.subarray(start + delimiter.length, nextStart));
    offset = nextStart;
  }
  return segments
    .map((segment) => {
      const splitAt = segment.indexOf('\r\n\r\n');
      if (splitAt === -1) return undefined;
      const rawHeaders = segment.subarray(0, splitAt).toString('utf8');
      const headers: Record<string, string> = {};
      for (const line of rawHeaders.split('\r\n')) {
        const colon = line.indexOf(':');
        if (colon <= 0) continue;
        const key = line.slice(0, colon).trim().toLowerCase();
        // eslint-disable-next-line security/detect-object-injection -- key comes from the multipart header, not user input
        headers[key] = line.slice(colon + 1).trim();
      }
      return { body: segment.subarray(splitAt + 4), headers };
    })
    .filter((part) => part !== undefined);
}

/**
 * Starts a static file server for the fixture directory on an ephemeral port.
 * @returns Server base URL and a close function.
 */
export async function startFixtureServer(): Promise<{
  close: () => Promise<void>;
  url: string;
}> {
  const server: Server = createServer((request, response) => {
    const url = new URL(request.url ?? '/', 'http://localhost');
    const file = path.join(FIXTURES_DIR, path.normalize(url.pathname));
    // eslint-disable-next-line security/detect-non-literal-fs-filename -- fixture path is test-controlled
    fs.readFile(file, (error, data) => {
      if (error) {
        response.statusCode = 404;
        response.setHeader('content-length', 0);
        response.end('not found');
        return;
      }
      const ext = path.extname(file).toLowerCase();
      // eslint-disable-next-line security/detect-object-injection -- ext comes from the fixture path
      response.setHeader('content-type', MIME[ext] ?? 'application/octet-stream');
      response.setHeader('content-length', data.length);
      response.end(data);
    });
  });
  server.listen(0, '127.0.0.1');
  // Keep keep-alive sockets open for the whole suite: the app drains fixture
  // bodies at FFmpeg's pace (DNA runs can exceed Node's 5s default), and a FIN
  // delivered while undici's parser is paused trips its internal assert.
  server.keepAliveTimeout = 10 * 60 * 1000;
  server.headersTimeout = 10 * 60 * 1000 + 1000;
  await once(server, 'listening');
  const address = server.address();
  if (address === null || typeof address === 'string') {
    throw new Error('fixture server has no address');
  }
  return {
    close: () =>
      new Promise<void>((resolve, reject) => {
        server.close((error) => (error ? reject(error) : resolve()));
      }),
    url: `http://127.0.0.1:${address.port}`,
  };
}
